// Pure builders for the vault's generated Map-of-Content pages — the entry
// point Obsidian readers get into an otherwise flat pile of notes. Topic
// structure comes from the computed link graph (shared/community.ts clusters
// over _links.jsonl edges); origin structure from the `project:` frontmatter
// tag. Everything here is data → markdown string: fs, the MOCs/ subfolder
// placement, and the change-only writes live in vault-linker-run.writeMocs.
// The pages are whole generated files regenerated on every link recompute,
// NOT marker-managed blocks — none of vault-related-core's markers appear in
// them — and they live in a subfolder precisely so no hub vault reader (all
// top-level-only scans) ever parses them back.

export interface MocNote {
  id: string
  excerpt: string | null
  project: string | null
}

export interface MocEdge {
  source: string
  target: string
}

const GENERATED_NOTICE =
  '<!-- generated by claude-hub (vault-moc-core) — do not edit; regenerated whenever vault links recompute -->'

const EXCERPT_MAX = 100

// MOC bullets need a CONTENT preview, but nearly every note opens with an H1
// equal to its filename — vault-graph's firstLineExcerpt would make each
// bullet read "[[Title]] — Title". Skip a leading line that is just the note's
// own title (compared loosely: filenames sanitize characters the H1 keeps,
// e.g. "/" → "-") and excerpt the first real prose line instead.
export function mocExcerpt(body: string, id: string): string | null {
  const norm = (s: string) => s.toLowerCase().replace(/[^a-z0-9]+/g, '')
  const lines = body
    .split('\n')
    .map((l) => l.trim().replace(/^#+\s*/, ''))
    .filter((l) => l.length > 0)
  const start = lines.length > 0 && norm(lines[0]) === norm(id) ? 1 : 0
  return lines[start] ?? null
}

function byIdAsc(a: MocNote, b: MocNote): number {
  return a.id < b.id ? -1 : a.id > b.id ? 1 : 0
}

// One list entry: wikilink + truncated first-line excerpt (excerpt-less notes
// get the bare link — no dangling dash).
function bullet(note: MocNote): string {
  if (!note.excerpt) return `- [[${note.id}]]`
  const text =
    note.excerpt.length <= EXCERPT_MAX ? note.excerpt : `${note.excerpt.slice(0, EXCERPT_MAX).trimEnd()}…`
  return `- [[${note.id}]] — ${text}`
}

// MOCs/Map of Content.md: one section per link-graph community (2+ members),
// biggest first, headed by the cluster's highest-degree note (its hub), with
// members listed degree-first; singleton/edge-less notes close the file under
// "Unlinked". Every sort carries an id tiebreaker so regeneration without a
// data change is byte-identical.
export function buildTopicMoc(notes: MocNote[], edges: MocEdge[], clusters: Map<string, number>): string {
  const degree = new Map<string, number>()
  for (const e of edges) {
    degree.set(e.source, (degree.get(e.source) ?? 0) + 1)
    degree.set(e.target, (degree.get(e.target) ?? 0) + 1)
  }
  const byDegreeDesc = (a: MocNote, b: MocNote) =>
    (degree.get(b.id) ?? 0) - (degree.get(a.id) ?? 0) || byIdAsc(a, b)

  const groups = new Map<number, MocNote[]>()
  for (const n of notes) {
    const c = clusters.get(n.id)!
    const members = groups.get(c)
    if (members) members.push(n)
    else groups.set(c, [n])
  }
  const sections = [...groups.values()]
    .filter((g) => g.length >= 2)
    .map((g) => g.sort(byDegreeDesc))
    .sort((a, b) => b.length - a.length || byIdAsc(a[0], b[0]))
  const unlinked = [...groups.values()]
    .filter((g) => g.length === 1)
    .flat()
    .sort(byDegreeDesc)

  const lines: string[] = [
    GENERATED_NOTICE,
    `${notes.length} notes · ${edges.length} edges · ${sections.length} clusters`,
  ]
  for (const g of sections) {
    lines.push('', `## Around: ${g[0].id}`, ...g.map(bullet))
  }
  if (unlinked.length > 0) {
    lines.push('', '## Unlinked', ...unlinked.map(bullet))
  }
  return `${lines.join('\n')}\n`
}

// MOCs/By origin.md: one section per `project:` frontmatter value — origin
// tagging (where a finding was discovered), deliberately not topic. Biggest
// origin first; notes without the tag pool under "untagged", always last.
export function buildOriginMoc(notes: MocNote[]): string {
  const groups = new Map<string, MocNote[]>()
  for (const n of notes) {
    const origin = n.project || 'untagged'
    const members = groups.get(origin)
    if (members) members.push(n)
    else groups.set(origin, [n])
  }
  const sections = [...groups.entries()].sort((a, b) => {
    if (a[0] === 'untagged') return 1
    if (b[0] === 'untagged') return -1
    return b[1].length - a[1].length || (a[0] < b[0] ? -1 : 1)
  })

  const lines: string[] = [GENERATED_NOTICE]
  for (const [origin, members] of sections) {
    lines.push('', `## ${origin}`, ...members.sort(byIdAsc).map(bullet))
  }
  return `${lines.join('\n')}\n`
}
